import {renderManagement,initLibrary} from './management.js';
import {initLiveScan} from './live.js';
import {normalizeBatch,validateDetection} from './batch.js';
import {detectItem} from './ai.js';
const providers={apinex:{name:'Apinex'},google:{name:'Google Gemini'}};
import {rules,items,matchItems} from './catalog.js';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let provider='apinex',key='',photo=null,tab='photo',current=null,busy=false,activeHistoryId=null,batch=null;
let live=null;let history=[];try{history=JSON.parse(localStorage.getItem('wastewise-history')||'[]');if(!Array.isArray(history))history=[];history=history.filter(x=>x&&typeof x.name==='string'&&typeof x.category==='string'&&typeof x.date==='string').slice(0,100);}catch{}
function updateCount(){$('#historyCount').textContent=history.length+(live?.count||0);}updateCount();
function view(name){if(name!=='sort')live?.pause();['sort','history','guide'].forEach(v=>{$('#'+v+'View').hidden=v!==name;document.querySelectorAll('.nav[data-view="'+v+'"]').forEach(b=>{b.classList.toggle('active',v===name);if(v===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});});if(name==='history')renderHistory();window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
function changeTab(t){if(t!=='live')live?.pause();tab=t;$('#livePanel').hidden=t!=='live';$('#liveOutput').hidden=t!=='live';$('#sortButton').hidden=t==='live';$('.privacy').hidden=t==='live';if(t==='live')$('#result').hidden=true;$('#photoPanel').hidden=t!=='photo';$('#textPanel').hidden=t!=='text';document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));$('#message').textContent='';}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>changeTab(b.dataset.tab));
async function loadPhoto(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){$('#message').textContent='Please choose a JPG, PNG or WEBP image smaller than 8 MB.';return;}try{const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);});const image=await new Promise((res,rej)=>{const image=new Image();image.onload=()=>res(image);image.onerror=rej;image.src=data;});const scale=Math.min(1,1280/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext('2d');if(!context)throw Error('Image processing unavailable');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);const prepared=canvas.toDataURL('image/jpeg',0.82);photo={data:prepared,mime:'image/jpeg'};$('#preview').src=prepared;$('#preview').hidden=false;$('#uploadPlaceholder').hidden=true;$('#removePhoto').hidden=false;$('#message').textContent='';$('#result').hidden=true;}catch{$('#message').textContent='This image could not be read. Please choose another photo.';}}
$('#photo').onchange=e=>loadPhoto(e.target.files[0]);$('#cameraPhoto').onchange=e=>loadPhoto(e.target.files[0]);$('#takePhoto').onclick=()=>{ $('#cameraPhoto').value='';$('#cameraPhoto').click(); };$('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#photo').click();}};$('#removePhoto').onclick=()=>{photo=null;$('#photo').value='';$('#cameraPhoto').value='';$('#preview').hidden=true;$('#preview').removeAttribute('src');$('#uploadPlaceholder').hidden=false;$('#removePhoto').hidden=true;};
['dragover','dragleave','drop'].forEach(event=>$('#dropzone').addEventListener(event,e=>{e.preventDefault();$('#dropzone').classList.toggle('drag',event==='dragover');if(event==='drop')loadPhoto(e.dataTransfer.files[0]);}));
function showResult(html){$('#result').innerHTML=html;$('#result').hidden=false;document.activeElement?.blur();$('#result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function choose(question,candidates=items){current=null;showResult('<span class="badge">One quick check</span><h2>Let’s make sure.</h2><p>'+esc(question)+'</p><div>'+candidates.map(i=>'<button class="choice" data-item="'+esc(i.name)+'">'+esc(i.name)+'</button>').join('')+'</div><p class="hint">If none match, describe another item or check with campus facilities. We won’t guess a bin.</p>');$('#result').querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>identify(items.find(i=>i.name===b.dataset.item),'Confirmed by you'));}
function identify(item,source='Demo catalog match',condition,{save=true}={}){if(item.name==='Pizza box'&&!condition){showResult('<span class="badge">Condition matters</span><h2>Is the pizza box greasy?</h2><p>Food residue changes the sorting rule. Choose the condition you can see.</p><button class="choice" data-condition="clean">Clean and dry</button><button class="choice" data-condition="greasy">Greasy or food-soiled</button><button class="choice" data-condition="mixed">Some clean, some greasy</button>');$('#result').querySelectorAll('[data-condition]').forEach(b=>b.onclick=()=>identify(item,'Condition confirmed by you',b.dataset.condition));return;}
const selected=rules.find(r=>r.id===(condition==='greasy'?'R7':item.rule));const split=item.name==='Coffee cup'||condition==='mixed';current={name:item.name,material:item.material,category:split?'Separate components':selected?.category||'Check collection',rule:selected?.id||'',item:item.name,certain:!!selected,identified:true,quantity:1,condition:condition||'',source};
showResult('<span class="badge">'+esc(source)+'</span><h2>'+esc(item.name)+'</h2><p>Suggested material: <strong>'+esc(item.material)+'</strong></p><h3>'+esc(current.category)+'</h3>'+(item.name==='Coffee cup'?'<p><strong>Cup → General waste</strong><br>Rigid plastic lid, if present → Dry recycling</p>':condition==='mixed'?'<p>Clean cardboard → Dry recycling<br>Greasy sections → General waste</p>':'')+(selected?'<div class="rule"><strong>Preparation &amp; supporting rule · '+selected.id+'</strong>“'+esc(selected.text)+'”<br><small>Greenfield Campus · Sample guide v1.0</small></div>':'<div class="notice">Item identified. This sample guide has no collection rule; ask campus facilities.</div>')+'<div class="result-actions"><span class="badge" id="saveStatus">Saving to history…</span><button class="secondary" id="correct">Correct identification</button><button class="text-button" id="seeGuide">View full guide ↗</button></div><p class="hint">Sample guidance only. Confirm your real locality’s rules before disposal.</p>'+renderManagement([current]));
if(save){const existing=history.find(x=>x.id===activeHistoryId);const entry={...current,id:activeHistoryId||crypto.randomUUID(),date:existing?.date||new Date().toISOString(),updatedAt:new Date().toISOString()};const next=[entry,...history.filter(x=>x.id!==entry.id)].slice(0,100);try{localStorage.setItem('wastewise-history',JSON.stringify(next));history=next;activeHistoryId=entry.id;updateCount();$('#saveStatus').textContent='Saved automatically ✓';}catch{$('#saveStatus').textContent='History could not be saved';$('#message').textContent='Browser storage is full or unavailable.';}}else $('#saveStatus').textContent='Saved in history ✓';$('#correct').onclick=()=>choose('What should this item be identified as? Your correction updates this history entry.');$('#seeGuide').onclick=()=>view('guide');}
async function analyze(){if(busy)return;activeHistoryId=null;batch=null;$('#message').textContent='';const description=$('#description').value.trim();if(tab==='photo'&&!photo){$('#message').textContent='Add a photo first, or switch to describing your item.';return;}if(tab==='text'&&!description){$('#message').textContent='Describe your item first.';$('#description').focus();return;}
if(!key){if(tab==='photo'){$('#message').textContent='Automatic photo detection is not configured yet. The site owner needs to add the server API key.';return;}if(/broken|chemical|medical|needle/i.test(description)){choose('This may need special handling beyond our sample catalog. Please consult campus facilities; only choose an item below if it accurately matches.',[]);return;}const matches=matchItems(description);if(matches.length===1){const condition=matches[0].name==='Pizza box'?(/greasy|oily|soiled/i.test(description)?'greasy':/clean|dry/i.test(description)?'clean':undefined):undefined;identify(matches[0],undefined,condition);}else choose(matches.length?'A few items could match. Which one do you mean?':'I don’t have enough information to identify that item. Does one of these match?',matches.length?matches:items);return;}
busy=true;$('#sortButton').disabled=true;$('#sortButton').textContent='Checking with Gemini…';$('#result').hidden=true;
try{const answer=await detectItem({description:tab==='text'?description:'',photo:tab==='photo'?photo:null});batch=normalizeBatch(answer);batch.id=crypto.randomUUID();batch.date=new Date().toISOString();batch.entries=batch.entries.map(entry=>({...entry,id:crypto.randomUUID()}));persistBatch();renderBatch();
}catch(e){$('#message').textContent=e.name==='TimeoutError'?'The request took too long. Try again or switch to demo mode.':e instanceof SyntaxError?'Gemini returned an unreadable answer. Please try again.':e.message;}finally{busy=false;$('#sortButton').disabled=false;$('#sortButton').innerHTML='Find the right bin <span>↗</span>';}}
$('#sortButton').onclick=analyze;document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{if(busy)return;view('sort');changeTab('text');$('#description').value=b.dataset.example;activeHistoryId=null;identify(items.find(i=>i.name===b.dataset.example));});
function renderHistory(){live?.refresh();$('#historyList').innerHTML=history.length?history.map((x,index)=>'<article class="history-card"><span class="badge">'+esc(x.category)+'</span><h3>'+esc(x.name)+'</h3><p>'+esc(x.material||'')+'</p><small>'+esc(new Date(x.date).toLocaleString())+' · Sample guide v1.0 · '+esc(x.rule||'')+(x.batchId?' · Photo group · '+esc(x.quantity||1)+' visible · '+esc(x.location||''): '')+'</small><br><button class="text-button" data-review="'+index+'">Review guidance</button><button class="text-button" data-delete="'+index+'">Delete</button></article>').join(''):'<div class="guide-card"><h3>A fresh start.</h3><p>Sort an item. Successful results save automatically. Your history will appear here.</p><button class="secondary" id="startSorting">Sort your first item ↗</button></div>';if(!history.length&&live?.count)$('#historyList').innerHTML='';$('#clearHistory').hidden=!history.length;if($('#startSorting'))$('#startSorting').onclick=()=>view('sort');document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const entry=history[Number(b.dataset.review)];const item=items.find(i=>i.name===entry.name);if(item){batch=null;activeHistoryId=entry.id||null;view('sort');identify(item,'Saved identification',entry.condition,{save:false});}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{saveHistory(history.filter((_,i)=>i!==Number(b.dataset.delete)));});}
function saveHistory(next){try{localStorage.setItem('wastewise-history',JSON.stringify(next));history=next;updateCount();renderHistory();}catch{alert('History could not be updated. Browser storage is unavailable.');}}
$('#clearHistory').onclick=()=>{if(confirm('Clear all saved disposal history on this browser?'))saveHistory([]);};
$('#guideRules').innerHTML=rules.map(r=>'<article class="guide-card"><span class="badge">'+r.id+' · '+r.category+'</span><h3>'+r.title+'</h3><p>'+r.text+'</p></article>').join('');

$('#settingsButton').onclick=()=>$('#settings').showModal();
async function loadServerStatus(){try{const response=await fetch('/api/config',{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();provider=data.provider==='google'?'google':'apinex';key=data.configured?'server-managed':'';$('#modeLabel').textContent=key?'AI ready':'AI setup pending';$('.privacy').textContent=key?'Photos are analyzed securely through the site server.':'Photo AI is waiting for the owner’s server configuration.';$('#serverStatus').textContent=key?'AI is ready. Upload a photo or describe your waste to get started.':'Photo recognition will be available once the site owner configures the server API key. You can try the demos now.';}catch{$('#modeLabel').textContent='AI unavailable';$('#serverStatus').textContent='The analysis server is temporarily unavailable. Please try again later.';}}
loadServerStatus();

function persistBatch(){
 if(!batch)return;const ready=batch.entries.filter(e=>e.certain||e.identified).map(e=>({...e,batchId:batch.id,date:batch.date,updatedAt:new Date().toISOString(),source:batch.source||providers[provider].name+' · AI photo group'}));
 const next=[...ready,...history.filter(h=>h.batchId!==batch.id)].slice(0,100);
 try{localStorage.setItem('wastewise-history',JSON.stringify(next));history=next;batch.saved=true;updateCount();}catch{batch.saved=false;$('#message').textContent='Results are ready, but browser storage is unavailable. History could not be saved.';}
}
function renderBatch(scroll=true){
 if(!batch)return;const ready=batch.entries.filter(e=>e.certain).length,unclear=batch.entries.length-ready;
 const html='<div class="batch-heading"><span class="badge">'+ready+' identified · '+unclear+' need a check</span><h2>Let’s sort your waste.</h2><p>'+esc(batch.overview||'Each object gets its own guidance. Check the descriptions and positions against your photo.')+'</p></div>'+(batch.incomplete?'<div class="notice">This scene may contain hidden or additional objects. These are the visible items identified so far. Take a closer photo of the remaining pile.</div>':'')+'<p class="hint">'+(batch.saved?'Identified items saved automatically, including items needing a collection check. Unclear objects are saved after confirmation.':'History could not be saved.')+' · Sample campus guide</p><div class="batch-grid">'+batch.entries.map((entry,index)=>{
 const rule=rules.find(r=>r.id===entry.rule);
 return '<article class="batch-card" data-entry="'+index+'"><span class="badge">Item '+(index+1)+' · '+(entry.certain||entry.identified?esc(entry.category):'Needs a closer look')+'</span><h3>'+esc(entry.certain?entry.name:entry.label)+'</h3><p class="object-location">'+esc(entry.location||'Position not specified')+' · '+entry.quantity+' visible</p><p>'+esc(entry.label)+'</p>'+(entry.certain?'<p>Material: <strong>'+esc(entry.material)+'</strong></p>'+(entry.name==='Coffee cup'?'<p><strong>Cup → General waste</strong><br>Rigid plastic lid, if present → Dry recycling</p>':entry.condition==='mixed'?'<p>Clean cardboard → Dry recycling<br>Greasy sections → General waste</p>':'')+'<div class="rule"><strong>Preparation &amp; supporting rule · '+esc(rule.id)+'</strong>“'+esc(rule.text)+'”<br><small>Greenfield Campus · Sample guide v1.0</small></div>':'<div class="notice">'+esc(entry.question)+'</div>')+'<button class="secondary" data-edit-entry="'+index+'">'+(entry.certain||entry.identified?'Correct this item':'Identify this object')+'</button><button class="text-button" data-ignore-entry="'+index+'">Not a waste item</button><div id="entryEditor'+index+'" hidden></div></article>';
 }).join('')+'</div><p class="hint">Small or hidden objects can be missed. Take another close-up if you can’t match an object to a result.</p>';
 if(scroll)showResult(html+renderManagement(batch.entries));else $('#result').innerHTML=html+renderManagement(batch.entries);
 $('#result').querySelectorAll('[data-edit-entry]').forEach(b=>b.onclick=()=>editBatchEntry(Number(b.dataset.editEntry)));
 $('#result').querySelectorAll('[data-ignore-entry]').forEach(b=>b.onclick=()=>{batch.entries.splice(Number(b.dataset.ignoreEntry),1);persistBatch();if(batch.entries.length)renderBatch(false);else showResult('<h2>No waste items remain.</h2><p>Upload another photo to sort something else.</p>');});
}
function editBatchEntry(index){
 const entry=batch.entries[index],editor=$('#entryEditor'+index);editor.hidden=false;
 editor.innerHTML='<label class="field-label" for="correctItem'+index+'">What is this object?</label><select id="correctItem'+index+'"><option value="">Choose the item you can confirm</option>'+items.map(i=>'<option value="'+esc(i.name)+'" '+(i.name===entry.item?'selected':'')+'>'+esc(i.name)+'</option>').join('')+'</select><label class="field-label" for="correctCondition'+index+'">Pizza box condition (if applicable)</label><select id="correctCondition'+index+'"><option value="">Choose condition if needed</option><option value="clean">Clean and dry</option><option value="greasy">Greasy or food-soiled</option><option value="mixed">Both clean and greasy sections</option></select><p class="hint">Only select a match you can confirm. If this object is not listed, ask campus facilities or take a closer photo.</p><button class="primary" id="applyEntry'+index+'">Update this item</button><p id="editMessage'+index+'" role="status"></p>';
 $('#correctCondition'+index).value=entry.condition;
 $('#applyEntry'+index).onclick=()=>{const item=items.find(i=>i.name===$('#correctItem'+index).value);if(!item){$('#editMessage'+index).textContent='Choose the item you can confirm.';return;}const condition=item.name==='Pizza box'?$('#correctCondition'+index).value:'';if(item.name==='Pizza box'&&!condition){$('#editMessage'+index).textContent='Please confirm the condition of this pizza box.';return;}
 const updated=validateDetection({item:item.name,label:item.name+' · corrected by you',location:entry.location,quantity:entry.quantity,condition,certain:true,ruleId:item.name==='Pizza box'&&condition==='greasy'?'R7':item.rule});batch.entries[index]={...updated,id:entry.id};persistBatch();renderBatch(false);};
}

$('#mixedDemo').onclick=()=>{if(busy)return;view('sort');batch=normalizeBatch({overview:'Demo: a scattered bottle, coffee cup, greasy pizza box and one obscured object.',incomplete:true,items:[{item:'Plastic bottle',label:'Empty plastic drink bottle',location:'Upper left',quantity:2,certain:true,ruleId:'R1'},{item:'Coffee cup',label:'Lined takeaway cup with lid',location:'Centre',quantity:1,certain:true,ruleId:'R6'},{item:'Pizza box',label:'Food-soiled cardboard box',location:'Lower right',quantity:1,certain:true,condition:'greasy',ruleId:'R7'},{item:null,label:'Partly hidden packaging',location:'Under the box',quantity:1,certain:false,question:'Can you take a closer photo or confirm the material?'}]});batch.id=crypto.randomUUID();batch.date=new Date().toISOString();batch.source='Mixed pile demo';batch.entries=batch.entries.map(e=>({...e,id:crypto.randomUUID()}));persistBatch();renderBatch();};

live=initLiveScan({navigate:()=>{view('sort');changeTab('live');},isReady:()=>!!key,onCount:()=>updateCount()});
initLibrary();
$('#householdDemo').onclick=()=>{if(busy)return;view('sort');changeTab('text');batch=normalizeBatch({overview:'Household demo: food scraps, packaging, e-waste and a collection check.',items:[{item:'Banana peel',certain:true,ruleId:'R5',quantity:2},{item:'Plastic bottle',certain:true,ruleId:'R1'},{item:'Laptop',certain:true,ruleId:'R8'},{item:'AA battery',certain:true,ruleId:'R8',quantity:3},{item:'Pizza box',certain:true,ruleId:'R2',condition:'mixed'},{item:'Coffee grounds',certain:true,ruleId:null}]});batch.id=crypto.randomUUID();batch.date=new Date().toISOString();batch.source='Household and e-waste demo';batch.entries=batch.entries.map(e=>({...e,id:crypto.randomUUID()}));persistBatch();renderBatch();};
